# ---- Dependency guard ----
try:
    from Crypto.Cipher import AES
    from Crypto.Util.Padding import unpad
except ModuleNotFoundError:
    print("[FATAL] Missing dependency: pycryptodome")
    print("Install with: python -m pip install pycryptodome")
    sys.exit(1)

# ---- Python version guard (AUTO) ----
EXPECTED_PY = (3, 13)

if sys.version_info[:2] != EXPECTED_PY:
    print("[FATAL] Unsupported Python version")
    print(f"Expected: {EXPECTED_PY[0]}.{EXPECTED_PY[1]}")
    print(f"Found:    {sys.version_info[0]}.{sys.version_info[1]}")
    sys.exit(1)

def _xor(parts):
    from functools import reduce
    return reduce(lambda a,b: bytes(x^y for x,y in zip(a,b)), parts)

_KEY = _xor([b"\xcf\xee0\x19\xf3\xec\xf2^-\x97\x8eo\x83G\\-\x170\x0bH~\xde\xad\xdeH\x96\xd6'\x02\xba\xd9\xfe", b'\x92\x86\x13\xbe\xb6^\x18\xf2^A\xb6\x9a\xdd}\x95\xf5+1\x8e\xf3v\xc1\x89\xd0\xa8b\xa2\x0b\xa1\x93\xf6\xbf', b'\x1e\xe8\xdf+G\x84\x18 8e\xaf\xb0\x92\x87\x9dg\xbf\xaab!#\xa7\x7f\xbafG\xc2{5\xa1\x8dy'])
_IV  = _xor([b'\x7f\xbdu\x8c`\xdd%\xea\xa6\xbaC\xb9u1\xe5\xeb', b'4\x18\xfd\xe2\xd3vq\xffX\xc4j"\xf2h\xc7\x7f'])

def _decrypt_str(d):
    iv, p = d[:16], d[16:]
    return unpad(AES.new(_KEY, AES.MODE_CBC, iv).decrypt(p), 16).decode("utf-8", "ignore")

def _decrypt_bytes(d):
    iv, p = d[:16], d[16:]
    return unpad(AES.new(_KEY, AES.MODE_CBC, iv).decrypt(p), 16)

